ST.xhtml:p:
(*状态机监控*)
IF LayerStartStateIn <> LayerStartStateIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(LayerStartStateIn+100000);
END_IF;
IF LayerEndStateIn <> LayerEndStateIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(LayerEndStateIn+200000);
END_IF;
(*随动*)
IF nFollowStateIn <> nFollowStateIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(nFollowStateIn+400000);
END_IF;
(*Z轴上抬*)

IF nLiftStateIn <> nLiftStateIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(nLiftStateIn+600000);
END_IF;

IF nFollowErrorStateIn <> nFollowErrorStateIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(nFollowErrorStateIn+800000);
END_IF;
(*这里为了读取随动下  z轴报错的 ERRORID*)
IF nZErrorIDIn <> 0 AND nZErrorIDIn <> 100 AND nZErrorIDIn <> 101 AND nZErrorIDIn <> nZErrorIDIn_1 THEN
  headIdx := (headIdx + 1) mod MaxLength;
  MachineStateBuffer[headIdx]:= DINT_TO_LREAL(nZErrorIDIn+900000);
END_IF;



LayerStartStateIn_1 := LayerStartStateIn;
LayerEndStateIn_1 := LayerEndStateIn;
nFollowStateIn_1 := nFollowStateIn;
nLiftStateIn_1 := nLiftStateIn;
nFollowErrorStateIn_1 := nFollowErrorStateIn;
nZErrorIDIn_1 := nZErrorIDIn;
